@router.get("/features/bootstrap/{workspace_id}")
async def bootstrap_workspace_flags(
    workspace_id: str,
    current_user: User = Depends(get_current_user)
):
    if workspace_id not in current_user.workspace_memberships:
        raise HTTPException(status_code=403, detail="Forbidden: access to target workspace flags denied")

    context = (
        Context.builder(workspace_id)
        .kind("workspace")
        .set("workspace_id", workspace_id)
        .build()
    )
    all_flags = ldclient.get().all_flags_state(context)
    return {"workspace_id": workspace_id, "flags": all_flags.to_json_dict()}
